// 布林带：取 60 日优先、其次 20 日
const bb = (mg.boll || []).reduce((acc, b) => { acc[b.n] = b; return acc; }, {});
r.boll60 = bb[60] || null;
r.boll20 = bb[20] || null;
// 信号分解：股息率达标(yldHit) 是唯一硬门槛；分位/布林带只作加分项（不单独触发买入）
const yldHit = (r.buyToTgtPct != null && r.buyToTgtPct >= 0);
const pctHit = (mg.yldPct != null && mg.yldPct >= 80);
const bollHit = !!(r.boll60 && r.boll60.belowLower);
r.marginStrength = (yldHit ? 2 : 0) + (pctHit ? 1 : 0) + (bollHit ? 1 : 0);
// 一票否决：未达股息率绝对阈值 → 不买（即使触及布林下轨或高分位，也只是加分）
r.marginBuy = !!yldHit;
r.yldHit = yldHit; r.pctHit = pctHit; r.bollHit = bollHit;
r.marginBonus = (pctHit ? '高股息分位' : '') + (bollHit ? (pctHit ? '、' : '') + '触布林下轨' : '');

