tool_input.new_string:
function buildPlan(amount, rows, T) {
  const R = RULES;
  const lot = R.lot || 100, maxS = +R.max_single || 25, maxI = +R.max_ind || 35;
  const shW = +R.sh_ratio || 0.6, skipP = +R.skip_premium || 3;
  const maxBuys = Math.max(1, +R.max_buys || 2);            // 本次最多买几只（摩擦成本控制）
  const minTicket = +R.min_ticket || 8000;                  // 单只最低买入额（避免 5 元最低佣金吃掉收益）
  const minFee = +S.settings.minFee || 5;                   // 券商双边最低佣金
  const base = T.mv + amount;
  const indUsed = {}, mktUsed = { '沪': 0, '深': 0 };
  rows.forEach(r => {
    if (r.mv <= 0) return;
    indUsed[r.ind] = (indUsed[r.ind] || 0) + r.mv;
    mktUsed[r.mkt] = (mktUsed[r.mkt] || 0) + r.mv;
  });

  const cands = [], skipped = [];
  const hasMargin = rows.some(r => r.margin);
  rows.filter(r => r.w > 0 && r.t).forEach(r => {
    r.capPct = Math.min(r.w, maxS);
    if (!r.price) { skipped.push({ r: r, why: '无行情' }); return; }
    // 硬门槛：有安全边际数据时，必须达股息率目标价（一票否决）；分位/布林带只作加分。
    if (hasMargin && r.margin) {
      if (!r.marginBuy) {
        const why = [];
        if (r.buyToTgtPct != null && r.buyToTgtPct < 0) why.push('距目标价还差 ' + fmt(-r.buyToTgtPct, 1) + '%');
        if (r.margin.yldPct != null) why.push('分位 ' + fmt(r.margin.yldPct, 0));
        skipped.push({ r: r, why: '未达股息率目标价（' + (why.join('，') || '指标未触发') + '）' });
        return;
      }
    } else if (r.skip) {
      skipped.push({ r: r, why: '溢价 ' + fmt(-r.disc, 1) + '%，等回落' }); return;
    }
    if (r.mv >= r.capPct / 100 * base - 1) {
      skipped.push({ r: r, why: r.mv > r.capPct / 100 * base + 1 ? '已超上限' : '已到上限' });
      return;
    }
    cands.push(r);
  });
  // 排序：股息率达标者中，安全边际强度优先，再按「现价低于目标价越多越优先」，最后 vwap 折价
  cands.sort((a, b) =>
    (b.marginStrength || 0) - (a.marginStrength || 0) ||
    ((b.buyToTgtPct || 0) - (a.buyToTgtPct || 0)) ||
    ((b.disc || 0) - (a.disc || 0)));

  let left = amount;
  const items = [];
  const mktBuyCount = { '沪': 0, '深': 0 };
  cands.forEach(r => {
    if (items.length >= maxBuys) { skipped.push({ r: r, why: '本次已达 ' + maxBuys + ' 只上限（省佣金）' }); return; }
    // 沪深各 1 只优先：若该市场已买到 1 只且还没买满，跳过以给另一市场机会
    if (items.length < maxBuys && mktBuyCount[r.mkt] >= Math.ceil(maxBuys / 2) && mktBuyCount[r.mkt] >= 1) {
      // 仅当还有另一市场的候选未尝试时才让位——简化：市场买满配额则跳
      if (mktBuyCount[r.mkt] >= maxBuys) { skipped.push({ r: r, why: '同市场已够' }); return; }
    }
    const capRoom = r.capPct / 100 * base - r.mv;
    const indRoom = maxI / 100 * base - (indUsed[r.ind] || 0);
    const mktRoom = (r.mkt === '沪' ? shW : 1 - shW) * base - (mktUsed[r.mkt] || 0);
    const want = Math.min(capRoom, indRoom, mktRoom, left);
    if (want <= 0) { skipped.push({ r: r, why: '额度已满' }); return; }
    // 摩擦控制：单只买入额尽量 ≥ minTicket，避免小额多笔被 5 元最低佣金吃掉
    const canMeetTicket = want >= minTicket;
    if (!canMeetTicket && items.length > 0) {
      skipped.push({ r: r, why: '剩余 ' + fmt(want, 0) + ' 元 < 单只门槛 ' + fmt(minTicket, 0) + '（不划算）' });
      return;
    }
    const sh = Math.floor(want / r.price / lot) * lot;
    if (sh <= 0) { if (left >= r.price * lot) skipped.push({ r: r, why: '额度不足 1 手' }); return; }
    const cost = sh * r.price;
    const fee = Math.max(cost * (+S.settings.comm || 0), minFee) + cost * (+S.settings.trans || 0);
    items.push({ r: r, shares: sh, cost: cost, fee: fee });
    left -= cost;
    mktBuyCount[r.mkt] = (mktBuyCount[r.mkt] || 0) + 1;
    indUsed[r.ind] = (indUsed[r.ind] || 0) + cost;
    mktUsed[r.mkt] = (mktUsed[r.mkt] || 0) + cost;
  });
  const spend = items.reduce((a, x) => a + x.cost, 0);
  const feeTotal = items.reduce((a, x) => a + x.fee, 0);
  const feePct = spend > 0 ? feeTotal / spend * 100 : 0;
  return { items: items, skipped: skipped, spend: spend, left: left, base: base, feeTotal: feeTotal, feePct: feePct, maxBuys: maxBuys, minTicket: minTicket };
}

