function renderPlan(rows, T) {
  // 增量资金优先：读「本次投入金额」输入框；空/0 则回退到 config 的 rules.capital
  const inEl = document.getElementById('inPlanAmount');
  const inputVal = inEl ? parseFloat(inEl.value) : NaN;
  const amount = (isFinite(inputVal) && inputVal > 0) ? inputVal : (+RULES.capital || 0);
  $('#planHead').textContent = amount
    ? fmt(amount, 0) + ' 元 · 本次投入' + ((isFinite(inputVal) && inputVal > 0) ? '（手动）' : '（默认本金）')
    : '未配置本金';
  const body = $('#planBody'), note = $('#planNote');
  const COLS = 9;
  const hasMargin = rows.some(r => r.margin);
  if (!amount) { body.innerHTML = '<tr><td colspan="' + COLS + '" class="dim" style="text-align:center;padding:16px">请在上面填写本次投入金额，或让 config.js 给出 rules.capital。</td></tr>'; return; }

